llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Perindoprilat, a high-transfer analogue sharing the carboxylic acid/amide core, showed 19% oral bioavailability in young healthy subjects, which is below the 20% threshold; however, the query contains additional ester and phosphinate prodrug motifs that increase lipophilicity and absorption potential.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C52"],
      "claim": "Maraviroc, a high-transfer analogue, has absolute oral bioavailability of 33% at 300 mg in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Perindopril, the ethyl ester prodrug of perindoprilat, has absolute oral bioavailability of about 75%, demonstrating that ester prodrug masking of a polar acid can yield high F; the query similarly contains ester and phosphinate masking groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "A stavudine phosphoramidate prodrug is reported to have high oral bioavailability, supporting the high-F potential of the query's phosphate/phosphinate prodrug scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "SAHA (vorinostat), a lipophilic amide/hydroxamic acid, has 43% oral bioavailability in humans, supporting high F for the query's amide-containing lipophilic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Actisomide, a structurally related amide/amine with a phenyl group, has absolute oral bioavailability of 30-43% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer experimental analogues show absolute oral bioavailability above 20% (23-75%), and the query's ester/phosphinate prodrug features are associated with improved absorption. The main sub-threshold value (perindoprilat 19%) is outweighed by the prodrug-masked, more lipophilic query structure and by multiple supportive human F measurements.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "Uncertainty about whether the phosphinate/ester prodrug is cleaved and absorbed intact.",
    "Potential dose, formulation, and food effects on oral bioavailability.",
    "Disease-state bioavailability values may not reflect healthy-subject exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

